using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF 9 changed the discriminator property from "Discriminator" to "$type".
            // Preserve "Discriminator" so existing 500K documents remain readable and
            // raw SQL queries (WHERE c.Discriminator = ...) keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF 9 changed id format from "EntityType|Key" to just "Key".
            // Preserve the "EntityType|Key" format so existing documents stay accessible.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // HasIndex() now throws on Cosmos — removed.
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

